entries[30560] = { ["name"] = "Super Sapper Charge", ["text"] = "25 sec cast\nReagents:\nNetherweave Cloth (4), Elemental Blasting Powder (4), Primal Mana\n(2)\nRequires Engineering\n(340)\n\nUse: Explodes when triggered, dealing 900 to 1500 Fire damage to all enemies nearby and 675 to 1125 damage to you. (5 Min Cooldown)" }
entries[30561] = { ["name"] = "Goblin Tonk Controller", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nFel Iron Casing , Handful of Fel Iron Bolts (4), Gold Power Core" }
