entries[30563] = { ["name"] = "Goblin Rocket Launcher", ["text"] = "12.5 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Adamantite Tube (2), Khorium Power Core , Felsteel Stabilizer (2), Primal Fire (6), Primal Earth (6), Delicate Arcanite Converter (2)\nGoblin Rocket Launcher\nBinds when equipped\nTrinket\n+45 Stamina\nRequires Engineering\n(350)\nRequires Goblin Engineer\nUse: Fire a powerful rocket at the enemy that does 960 to 1440 damage and stuns them for 3 sec. This thing has quite a kick though... (2 Min Cooldown)" }
entries[30564] = { ["name"] = "Worgen's Spite", ["text"] = "Instant\nTransforms the caster into a worgen, causing their ranged and melee attacks to deal 200 shadow damage.\n(2s cooldown)" }
entries[30565] = { ["name"] = "Foreman's Enchanted Helmet", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nShadowcloth (4), Primal Mana (12), Primal Air (12)\nForeman's Enchanted Helmet\nBinds when picked up\nHead Cloth\n132 Armor\n+48 Stamina\n+30 Intellect\nDurability 60 / 60\nRequires Engineering\n(350)\nRequires Goblin Engineer\nEquip: +10% Stun Resistance.\n\nEquip: Increases damage and healing done by magical spells and effects by up to 36." }
entries[30566] = { ["name"] = "Foreman's Reinforced Helmet", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Adamantite Bar (8), Primal Earth (12), Primal Fire (12)\nForeman's Reinforced Helmet\nBinds when picked up\nHead Mail\n550 Armor\n+30 Agility\n+48 Stamina\nDurability 85 / 85\nRequires Engineering\n(350)\nRequires Goblin Engineer\nEquip: Increases attack power by 62.\n\nEquip: Increases your chance to resist Stun and Disorient effects by 10%." }
entries[30567] = { ["name"] = "Torment of the Worgen", ["text"] = "Instant\nBreak the seal on the book, granting you a chance to deal additional shadow damage on ranged or melee attacks." }
entries[30568] = { ["name"] = "Gnomish Flame Turret", ["text"] = "25 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nAdamantite Frame , Handful of Fel Iron Bolts (2), Elemental Blasting Powder (3), Fel Iron Casing\n(3)\nRequires Engineering\n(325)\n\nUse: Quickly constructs a gnomish flame turret at your feet that will nearly always attack nearby enemies. The turret falls apart after 45 sec. (1 Min Cooldown)" }
entries[30569] = { ["name"] = "Gnomish Poultryizer", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Adamantite Tube (2), Khorium Power Core (2), Arcane Dust (10), Large Prismatic Shard (2)\nGnomish Poultryizer\nBinds when equipped\nTrinket\n+45 Stamina\nRequires Engineering\n(340)\nRequires Gnomish Engineer\nUse: Turns the target into a chicken for 15 sec. Well, that is assuming the transmogrification polarity has not been reversed... (5 Min Cooldown)" }
entries[30570] = { ["name"] = "Nigh-Invulnerability Belt", ["text"] = "45 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHeavy Knothide Leather (8), Khorium Power Core (4), Primal Life (10), Primal Shadow (10), Delicate Arcanite Converter (2)\nNigh Invulnerability Belt\nBinds when equipped\nWaist Cloth\n223 Armor\n+21 Stamina\nDurability 30 / 30\nRequires Engineering\n(350)\nUse: Protects you with a shield of force that stops 4000 damage for 8 sec. (5 Min Cooldown)\n\"Protection not always valid. In RARE cases wearer may take additional damage.\"" }
